-- Liberar reservas vencidas cada 10 minutos (si pg_cron está disponible)
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.schedule('beibidoll-liberar-reservas', '*/10 * * * *', 'select public.release_expired_orders()');
  end if;
exception when others then
  raise notice 'pg_cron no disponible: las reservas se liberan al crear pedidos o abrir el panel';
end $$;
